START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261017104840_AddNotificationOutbox') THEN
    CREATE TABLE notification_outbox (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "MessageId" uuid NOT NULL,
        "NotificationId" integer NOT NULL,
        "UserId" integer NOT NULL,
        "Channel" character varying(32) NOT NULL,
        "Account" character varying(64),
        "Ref" character varying(256),
        "Envelope" text,
        "CreatedAt" timestamp with time zone NOT NULL,
        "ExpiresAt" timestamp with time zone NOT NULL,
        "State" smallint NOT NULL,
        "SubmittedAt" timestamp with time zone,
        "SubmitError" character varying(1000),
        "ResultId" bigint,
        "ResultStatus" character varying(32),
        "ErrorKind" character varying(32),
        "ErrorCode" character varying(128),
        "ErrorMessage" character varying(1000),
        "ProviderMessageId" character varying(256),
        "DestinationInvalid" boolean NOT NULL,
        "Attempts" integer,
        "CompletedAt" timestamp with time zone,
        CONSTRAINT "PK_notification_outbox" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_notification_outbox_notification_NotificationId" FOREIGN KEY ("NotificationId") REFERENCES notification ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261017104840_AddNotificationOutbox') THEN
    CREATE TABLE notification_transport_cursor (
        "Name" character varying(64) NOT NULL,
        "Position" bigint NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_notification_transport_cursor" PRIMARY KEY ("Name")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory_Notifications" WHERE "MigrationId" = '20261017104840_AddNotificationOutbox') THEN
